using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PoisonCrazyCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PoisonCrazyCustomDescription", order = 0)]
public class SunnyFlaresCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SunnyFlaresAction sunnyFlaresAction = battleAction as SunnyFlaresAction;
		return base.localizationManager.GetLocalizedXTimesFormatted(sunnyFlaresAction.ReliefDefaultEffectAction.GetActionDescription(sunnyFlaresAction.FixedRelief).RemoveLast(), GetFinalAmountWithoutEquation(amountModified));
	}
}
